/// `ValueExpr = ValueOrExpr | ValueAndExpr | ValueNotExpr | ValueGroup | Term | Phrase | Comparison | Range`
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum ValueExpr {
    /// A `ValueOrExpr`.
    ValueOrExpr(ValueOrExpr),
    /// A `ValueAndExpr`.
    ValueAndExpr(ValueAndExpr),
    /// A `ValueNotExpr`.
    ValueNotExpr(ValueNotExpr),
    /// A `ValueGroup`.
    ValueGroup(ValueGroup),
    /// A `Term`.
    Term(Term),
    /// A `Phrase`.
    Phrase(Phrase),
    /// A `Comparison`.
    Comparison(Comparison),
    /// A `Range`.
    Range(Range),
}

impl AstNode for ValueExpr {
    type Language = Lang;
    fn can_cast(kind: SyntaxKind) -> bool {
        ValueOrExpr::can_cast(kind)
            || ValueAndExpr::can_cast(kind)
            || ValueNotExpr::can_cast(kind)
            || ValueGroup::can_cast(kind)
            || Term::can_cast(kind)
            || Phrase::can_cast(kind)
            || Comparison::can_cast(kind)
            || Range::can_cast(kind)
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let node = match syntax.kind() {
            SyntaxKind::VALUE_OR_EXPR => Self::ValueOrExpr(ValueOrExpr { syntax }),
            SyntaxKind::VALUE_AND_EXPR => Self::ValueAndExpr(ValueAndExpr { syntax }),
            SyntaxKind::VALUE_NOT_EXPR => Self::ValueNotExpr(ValueNotExpr { syntax }),
            SyntaxKind::VALUE_GROUP => Self::ValueGroup(ValueGroup { syntax }),
            SyntaxKind::TERM => Self::Term(Term { syntax }),
            SyntaxKind::PHRASE => Self::Phrase(Phrase { syntax }),
            SyntaxKind::COMPARISON => Self::Comparison(Comparison { syntax }),
            SyntaxKind::RANGE => Self::Range(Range { syntax }),
            _ => return None,
        };
        Some(node)
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::ValueOrExpr(it) => it.syntax(),
            Self::ValueAndExpr(it) => it.syntax(),
            Self::ValueNotExpr(it) => it.syntax(),
            Self::ValueGroup(it) => it.syntax(),
            Self::Term(it) => it.syntax(),
            Self::Phrase(it) => it.syntax(),
            Self::Comparison(it) => it.syntax(),
            Self::Range(it) => it.syntax(),
        }
    }
}

impl From<ValueOrExpr> for ValueExpr {
    fn from(node: ValueOrExpr) -> Self {
        Self::ValueOrExpr(node)
    }
}

impl From<ValueAndExpr> for ValueExpr {
    fn from(node: ValueAndExpr) -> Self {
        Self::ValueAndExpr(node)
    }
}

impl From<ValueNotExpr> for ValueExpr {
    fn from(node: ValueNotExpr) -> Self {
        Self::ValueNotExpr(node)
    }
}

impl From<ValueGroup> for ValueExpr {
    fn from(node: ValueGroup) -> Self {
        Self::ValueGroup(node)
    }
}

impl From<Term> for ValueExpr {
    fn from(node: Term) -> Self {
        Self::Term(node)
    }
}

impl From<Phrase> for ValueExpr {
    fn from(node: Phrase) -> Self {
        Self::Phrase(node)
    }
}

impl From<Comparison> for ValueExpr {
    fn from(node: Comparison) -> Self {
        Self::Comparison(node)
    }
}

impl From<Range> for ValueExpr {
    fn from(node: Range) -> Self {
        Self::Range(node)
    }
}

